import fc from "fast-check";
import { describe, expect, it } from "vitest";
import {
  BharatInputError,
  computeGSTINChecksum,
  generateTestGSTIN,
  generateTestPAN,
  listStates,
  TAX_DISCLAIMER,
  validateGSTIN,
  validatePAN,
} from "../src/index.js";

const CHARSET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
// Synthetic fixture, generated by generateTestGSTIN("29", { seed: 42 }).
const SYNTHETIC = generateTestGSTIN("29", { seed: 42 });

describe("validatePAN", () => {
  it("accepts a well-formed synthetic PAN and decodes the holder type", () => {
    const r = validatePAN(" abcpe1234f ");
    expect(r.valid).toBe(true);
    expect(r.normalized).toBe("ABCPE1234F");
    expect(r.entityType).toEqual({ code: "P", label: "Individual" });
  });

  it.each([
    ["ABCPE1234", "PAN_LENGTH"],
    ["ABCP11234F", "PAN_FORMAT"],
    ["ABCXE1234F", "PAN_ENTITY_TYPE"],
  ])("rejects %s with %s", (pan, code) => {
    const r = validatePAN(pan);
    expect(r.valid).toBe(false);
    expect(r.errors[0]?.code).toBe(code);
  });

  it("decodes every holder type", () => {
    for (const t of ["P", "C", "H", "F", "A", "T", "B", "L", "J", "G"]) {
      expect(validatePAN(`ABC${t}E1234F`).entityType?.code).toBe(t);
    }
  });
});

describe("validateGSTIN", () => {
  it("accepts a synthetic GSTIN and decodes its parts", () => {
    const r = validateGSTIN(SYNTHETIC.toLowerCase());
    expect(r.valid).toBe(true);
    expect(r.errors).toEqual([]);
    expect(r.stateCode).toBe("29");
    expect(r.stateName).toBe("Karnataka");
    expect(r.pan).toBe(SYNTHETIC.slice(2, 12));
    expect(r.panEntityType?.code).toBe("C");
    expect(r.entityNumber).toBe("1");
    expect(r.disclaimer).toBe(TAX_DISCLAIMER);
  });

  it("reports checksum mismatches with the expected character", () => {
    const expected = SYNTHETIC[14] as string;
    const wrong = expected === "0" ? "1" : "0";
    const r = validateGSTIN(SYNTHETIC.slice(0, 14) + wrong);
    expect(r.valid).toBe(false);
    expect(r.errors.map((e) => e.code)).toEqual(["GSTIN_CHECKSUM"]);
    expect(r.checksum).toEqual({ expected, actual: wrong });
  });

  it("rejects bad length and characters", () => {
    expect(validateGSTIN("29ABC").errors[0]?.code).toBe("GSTIN_LENGTH");
    expect(validateGSTIN("29ABCDE1234F1Z-").errors[0]?.code).toBe("GSTIN_CHARSET");
  });

  const withChecksum = (first14: string) => first14 + computeGSTINChecksum(first14);

  it("rejects unknown and non-GSTIN state codes", () => {
    expect(validateGSTIN(withChecksum("40ABCCE1234F1Z")).errors.map((e) => e.code)).toContain(
      "GSTIN_STATE",
    );
    expect(validateGSTIN(withChecksum("96ABCCE1234F1Z")).errors.map((e) => e.code)).toContain(
      "GSTIN_STATE",
    );
    expect(validateGSTIN(withChecksum("AAABCCE1234F1Z")).errors.map((e) => e.code)).toContain(
      "GSTIN_STATE",
    );
  });

  it("warns on legacy state codes and a non-Z 14th character", () => {
    const legacy = validateGSTIN(withChecksum("25ABCCE1234F1Z"));
    expect(legacy.valid).toBe(true);
    expect(legacy.warnings.map((w) => w.code)).toEqual(["GSTIN_STATE_LEGACY"]);
    const nonZ = validateGSTIN(withChecksum("29ABCCE1234F1D"));
    expect(nonZ.valid).toBe(true);
    expect(nonZ.warnings.map((w) => w.code)).toEqual(["GSTIN_DEFAULT_CHAR"]);
  });

  it("rejects a bad embedded PAN and a 0 registration number", () => {
    expect(validateGSTIN(withChecksum("29ABCXE1234F1Z")).errors.map((e) => e.code)).toEqual([
      "GSTIN_PAN_ENTITY_TYPE",
    ]);
    expect(validateGSTIN(withChecksum("29ABCCE1234F0Z")).errors.map((e) => e.code)).toEqual([
      "GSTIN_ENTITY_NUMBER",
    ]);
  });

  it("checksum input must be 14 valid characters", () => {
    expect(() => computeGSTINChecksum("29ABC")).toThrow(BharatInputError);
    expect(() => computeGSTINChecksum("29ABCCE1234F1-")).toThrow(BharatInputError);
  });
});

describe("generateTestGSTIN / generateTestPAN", () => {
  it("is deterministic for a seed", () => {
    expect(generateTestGSTIN("27", { seed: 7 })).toBe(generateTestGSTIN(27, { seed: 7 }));
    expect(generateTestPAN({ seed: 1, entityType: "P" })[3]).toBe("P");
    expect(validatePAN(generateTestPAN()).valid).toBe(true);
  });

  it("rejects state codes not usable in a GSTIN", () => {
    expect(() => generateTestGSTIN("96")).toThrow(BharatInputError);
    expect(() => generateTestGSTIN("00")).toThrow(BharatInputError);
  });

  const gstinStates = listStates({ includeLegacy: false })
    .filter((s) => s.gstinPrefix)
    .map((s) => s.code);

  it("property: generated GSTINs always validate", () => {
    fc.assert(
      fc.property(fc.constantFrom(...gstinStates), fc.integer(), (code, seed) => {
        const g = generateTestGSTIN(code, { seed });
        expect(validateGSTIN(g).valid).toBe(true);
      }),
      { numRuns: 500 },
    );
  });

  it("property: any single-character change to a valid GSTIN is caught", () => {
    fc.assert(
      fc.property(
        fc.integer(),
        fc.integer({ min: 0, max: 14 }),
        fc.integer({ min: 1, max: 35 }),
        (seed, pos, shift) => {
          const g = generateTestGSTIN("29", { seed });
          const original = CHARSET.indexOf(g[pos] as string);
          const replaced = CHARSET[(original + shift) % 36] as string;
          const mutated = g.slice(0, pos) + replaced + g.slice(pos + 1);
          expect(validateGSTIN(mutated).valid).toBe(false);
        },
      ),
      { numRuns: 1000 },
    );
  });
});
